    self.window = window_seconds
    self._last = {}
    # Keep sightings in time order so expired keys can be discarded without
    # scanning the whole mapping on every call.
    self._sightings = deque()

def seen(self, key, now):
    """Return True if ``key`` is a duplicate at time ``now``, else False.
    A False result records ``now`` as the key's latest new sighting."""
    cutoff = now - self.window
    while self._sightings and self._sightings[0][0] <= cutoff:
        timestamp, expired_key = self._sightings.popleft()
        if self._last.get(expired_key) == timestamp:
            del self._last[expired_key]

    last = self._last.get(key)
    if last is not None and now - last < self.window:
        return True
    self._last[key] = now
    self._sightings.append((now, key))
    return False

def __len__(self):
    return len(self._last)
